{
  "name": "@agentplugins/adapter-opencode",
  "version": "0.6.0",
  "description": "OpenCode platform adapter for AgentPlugins - generates OpenCode-compatible plugins from universal manifests",
  "type": "module",
  "main": "./dist/index.js",
  "types": "./dist/index.d.ts",
  "exports": {
    ".": {
      "import": "./dist/index.js",
      "require": "./dist/index.cjs",
      "types": "./dist/index.d.ts"
    }
  },
  "dependencies": {
    "zod": "^4.4.3",
    "@agentplugins/core": "0.6.0",
    "@agentplugins/compile": "0.6.0"
  },
  "devDependencies": {
    "tsup": "^8.0.0",
    "typescript": "^6.0.0",
    "vitest": "^4.0.0"
  },
  "files": [
    "dist",
    "README.md"
  ],
  "publishConfig": {
    "access": "public"
  },
  "license": "Apache-2.0",
  "repository": {
    "type": "git",
    "url": "https://github.com/sigilco/agentplugins.git",
    "directory": "packages/adapter-opencode"
  },
  "homepage": "https://agentplugins.pages.dev/",
  "keywords": [
    "agentplugins",
    "opencode",
    "adapter",
    "ai",
    "plugins"
  ],
  "scripts": {
    "build": "tsup src/index.ts --format cjs,esm --dts",
    "dev": "tsup src/index.ts --format cjs,esm --dts --watch",
    "clean": "rm -rf dist",
    "test": "vitest run --passWithNoTests",
    "test:run": "vitest run"
  }
}
